    public static String[] delimitedListToStringArray(String str, String delimiter) {

        if (str == null || str.isEmpty()) {
            return EMPTY_STRING_ARRAY;
        }
        if (delimiter == null) {
            return new String[] {str};
        }

        List<String> result = new ArrayList<>();
        if (delimiter.isEmpty()) {
